// MARK: - Generic tree node types used by the AVL/red-black contract tests

/// Boxed number because `BinaryNestedTree<T>` requires a class element (the app only uses
/// OriPoint/OriLine; the reference tests use numbers).
final class NumberBox: AnyObject {
    let value: Int
    init(_ value: Int) { self.value = value }
}

final class NumberAvlNode: AvlNode {
    let box: NumberBox
    private var _left: (any BinaryNode)?
    private var _right: (any BinaryNode)?

    init(_ box: NumberBox) {
        self.box = box
        super.init()
    }

    override func left() -> (any BinaryNode)? { _left }
    override func right() -> (any BinaryNode)? { _right }
    override func setLeft(_ node: (any BinaryNode)?) { _left = node }
    override func setRight(_ node: (any BinaryNode)?) { _right = node }

    override func compareTo(_ other: any BinaryNode) -> Int {
        guard let node = other as? NumberAvlNode else { return 0 }
        return (box.value - node.box.value).signum()
    }
}

final class NumberAvlTree: AvlNestedTree<NumberBox> {
    override func newNode(_ t: NumberBox) -> (any BinaryNode) { NumberAvlNode(t) }
    override func insertIntoNested(_ binaryNode: any BinaryNode, _ t: NumberBox) {}
    override func removeInNested(_ binaryNode: any BinaryNode, _ t: NumberBox) -> Bool { false }
    override func findExactInNested(_ binaryNode: any BinaryNode, _ t: NumberBox) -> NumberBox? {
        (binaryNode as? NumberAvlNode)?.box.value == t.value ? t : nil
    }
}

final class NumberRBNode: RedBlackNodeBase {
    let box: NumberBox
    init(_ box: NumberBox) {
        self.box = box
        super.init()
    }
    override func compareTo(_ other: any BinaryNode) -> Int {
        guard let node = other as? NumberRBNode else { return 0 }
        return (box.value - node.box.value).signum()
    }
}

final class NumberRBTree: RedBlackNestedTree<NumberBox> {
    override func newNode(_ t: NumberBox) -> (any BinaryNode) { NumberRBNode(t) }
    override func insertIntoNested(_ binaryNode: any BinaryNode, _ t: NumberBox) {}
    override func removeInNested(_ binaryNode: any BinaryNode, _ t: NumberBox) -> Bool { false }
    override func findExactInNested(_ binaryNode: any BinaryNode, _ t: NumberBox) -> NumberBox? {
        (binaryNode as? NumberRBNode)?.box.value == t.value ? t : nil
    }
    override func updateNode(_ binaryNode: any BinaryNode) {}
}

