// MARK: - Helpers

private func makePoint(_ x: Double, _ y: Double) -> OriPoint { OriPoint(x, y) }

private func makeLine(_ a: OriPoint, _ b: OriPoint, _ type: LineType = .mountain) -> OriLine {
    OriLine(a, b, type)
}

private func coords(_ line: OriLine) -> [Double] {
    [line.start.x, line.start.y, line.end.x, line.end.y]
}

private func coords(_ line: TreesFixture.LineCoords) -> [Double] {
    [line.x1, line.y1, line.x2, line.y2]
}

private func lexicographicSort(_ lines: [[Double]]) -> [[Double]] {
    lines.sorted { a, b in
        for index in 0..<min(a.count, b.count) where a[index] != b[index] {
            return a[index] < b[index]
        }
        return a.count < b.count
    }
}

private func sortedLineCoords(_ values: [OriLine]) -> [[Double]] {
    lexicographicSort(values.map(coords))
}

private func sortedPoints(_ values: [OriPoint]) -> [[Double]] {
    values.map { [$0.x, $0.y] }.sorted { a, b in
        a[0] == b[0] ? a[1] < b[1] : a[0] < b[0]
    }
}

private func blackHeight(_ node: (any BinaryNode)?) -> Int {
    guard let node else { return 1 }
    let left = blackHeight(node.left())
    let right = blackHeight(node.right())
    if left == 0 || right == 0 || left != right { return 0 }
    let isBlack = (node as? (any RedBlackNode))?.isBlack() ?? false
    return left + (isBlack ? 1 : 0)
}

private func inOrderValues(_ tree: NumberAvlTree) -> [Int] {
    var values: [Int] = []
    let iterator = tree.iterator()
    while iterator.hasNext() {
        if let node = iterator.next() as? NumberAvlNode { values.append(node.box.value) }
    }
    return values
}

private func inOrderValues(_ tree: NumberRBTree) -> [Int] {
    var values: [Int] = []
    let iterator = tree.iterator()
    while iterator.hasNext() {
        if let node = iterator.next() as? NumberRBNode { values.append(node.box.value) }
    }
    return values
}

private func fillPointTree(_ addLine: (OriLine) -> Void) {
    for row in 0..<10 {
        for column in 0..<9 {
            let start = makePoint(Double(column * 10), Double(row * 10))
            let end = makePoint(Double((column + 1) * 10), Double(row * 10))
            addLine(makeLine(start, end))
        }
    }
}

private func checkPointTreeFacade(
    _ h: TestHarness,
    expected: TreesFixture.PointTree,
    size: () -> Int,
    contains: (OriPoint) -> Bool,
    findPoint: (PointDouble, Double) -> NearestItem<OriPoint>,
    range: (PointDouble, PointDouble) -> JavaSet<OriPoint>,
    minMax: (Double) -> MinMaxDouble,
    iteration: () -> [[Double]],
    removeLine: (OriLine) -> Void,
    isEmpty: () -> Bool,
    clear: () -> Void
) {
    h.expectEqual(size(), expected.size, "point tree size")
    h.expectEqual(contains(makePoint(0, 0)), expected.containsOrigin, "contains origin")
    h.expectEqual(contains(makePoint(5, 5)), expected.containsInterior, "contains interior")
    let nearest = findPoint(PointDouble(51, 1), 5)
    if let expectedNearest = expected.nearest, let found = nearest.nearestItem {
        h.expectEqual([found.x, found.y], expectedNearest, "nearest point")
    } else {
        h.expectNil(nearest.nearestItem, "nearest point (expected nil)")
    }
    h.expectClose(nearest.distance, expected.nearestDistance, accuracy: 1e-9, "nearest distance")
    h.expectEqual(findPoint(PointDouble(5, 5), 1).nearestItem == nil, expected.missIsNull, "nearest miss")
    h.expectEqual(sortedPoints(range(PointDouble(-1, -1), PointDouble(21, 21)).values()),
                 lexicographicSort(expected.range), "points in range")
    let mm = minMax(200)
    h.expectClose(mm.minX, expected.minMax[0], "minMax.minX")
    h.expectClose(mm.minY, expected.minMax[1], "minMax.minY")
    h.expectClose(mm.maxX, expected.minMax[2], "minMax.maxX")
    h.expectClose(mm.maxY, expected.minMax[3], "minMax.maxY")
    h.expectEqual(iteration(), expected.iteration, "point iteration order")
    removeLine(makeLine(makePoint(80, 0), makePoint(90, 0)))
    h.expectEqual(size(), expected.sizeAfterRemoveLine, "point tree size after removeLine")
    h.expectEqual(contains(makePoint(90, 0)), !expected.removedPointGone, "removed point gone")
    clear()
    h.expectEqual(isEmpty(), expected.isEmptyAfterClear, "point tree cleared")
}

// MARK: - Suites

enum CoreTreeTests {
    static var all: [TestSuite] {
        [
            TestSuite("CoreTree.genericAVL") { h in
                let fixture = try Fixtures.decode(TreesFixture.self, "Fixtures/tree/trees.json")
                let expected = fixture.genericAVL
                let tree = NumberAvlTree()
                h.expect(tree.isEmpty(), "new AVL tree is empty")
                for value in expected.inserts { tree.insert(NumberBox(value)) }
                h.expect(!tree.isEmpty(), "tree not empty after inserts")
                h.expectEqual(inOrderValues(tree), expected.inorderAfterInsert, "in-order after inserts")
                h.expectEqual((tree.root() as? AvlNode)?.height() ?? -1, expected.heightAfterInsert, "AVL height")
                for check in expected.findExact {
                    let found = tree.findExact(NumberBox(check.value))
                    h.expectEqual(found?.value, check.expected, "findExact(\(check.value))")
                }
                for value in expected.removes { tree.remove(NumberBox(value)) }
                h.expectEqual(inOrderValues(tree), expected.inorderAfterRemove, "in-order after removals")
                tree.clear()
                h.expectEqual(tree.isEmpty(), expected.isEmptyAfterClear, "clear")
            },
            TestSuite("CoreTree.genericRB") { h in
                let fixture = try Fixtures.decode(TreesFixture.self, "Fixtures/tree/trees.json")
                let expected = fixture.genericRB
                let tree = NumberRBTree()
                for value in expected.inserts { tree.insert(NumberBox(value)) }
                h.expectEqual(inOrderValues(tree), expected.inorderAfterInsert, "in-order after inserts")
                h.expectEqual(tree.hasViolation(), expected.violationAfterInsert, "violation after inserts")
                h.expectEqual(blackHeight(tree.root()), expected.blackHeightAfterInsert, "black height after inserts")
                for value in expected.removes { tree.remove(NumberBox(value)) }
                h.expectEqual(inOrderValues(tree), expected.inorderAfterRemove, "in-order after removals")
                h.expectEqual(tree.hasViolation(), expected.violationAfterRemove, "violation after removals")
                h.expectEqual(blackHeight(tree.root()), expected.blackHeightAfterRemove, "black height after removals")
            },
            TestSuite("CoreTree.avlPoint") { h in
                let fixture = try Fixtures.decode(TreesFixture.self, "Fixtures/tree/trees.json")
                let expected = fixture.avlPoint
                let tree = AvlPointTree()
                fillPointTree { tree.addLine($0) }
                checkPointTreeFacade(
                    h, expected: expected,
                    size: { tree.size() },
                    contains: { tree.contains($0) },
                    findPoint: { tree.findPoint($0, $1) },
                    range: { tree.findAllPointsInRange($0, $1) },
                    minMax: { tree.getMinMax($0) },
                    iteration: {
                        var result: [[Double]] = []
                        var iterator = tree.iterator()
                        while iterator.hasNext() {
                            let point = iterator.next()
                            result.append([point.x, point.y])
                        }
                        return result
                    },
                    removeLine: { tree.removeLine($0) },
                    isEmpty: { tree.isEmpty() },
                    clear: { tree.clear() }
                )
            },
            TestSuite("CoreTree.rbPoint") { h in
                let fixture = try Fixtures.decode(TreesFixture.self, "Fixtures/tree/trees.json")
                let expected = fixture.rbPoint
                let tree = RedBlackPointTree()
                fillPointTree { tree.addLine($0) }
                checkPointTreeFacade(
                    h, expected: expected,
                    size: { tree.size() },
                    contains: { tree.contains($0) },
                    findPoint: { tree.findPoint($0, $1) },
                    range: { tree.findAllPointsInRange($0, $1) },
                    minMax: { tree.getMinMax($0) },
                    iteration: {
                        var result: [[Double]] = []
                        var iterator = tree.iterator()
                        while iterator.hasNext() {
                            let point = iterator.next()
                            result.append([point.x, point.y])
                        }
                        return result
                    },
                    removeLine: { tree.removeLine($0) },
                    isEmpty: { tree.isEmpty() },
                    clear: { tree.clear() }
                )
            },
            TestSuite("CoreTree.avlLine") { h in
                let fixture = try Fixtures.decode(TreesFixture.self, "Fixtures/tree/trees.json")
                let expected = fixture.avlLine
                let tree = AvlLineTree()
                let lines = expected.lines.map { makeLine(makePoint($0[0], $0[1]), makePoint($0[2], $0[3])) }
                for line in lines { tree.addLine(line) }
                h.expectEqual(tree.size(), expected.size, "line tree size")
                h.expectEqual(tree.contains(makeLine(makePoint(0, 0), makePoint(100, 0))), expected.containsByValue, "contains by value")
                h.expectEqual(tree.contains(makeLine(makePoint(100, 0), makePoint(0, 0))), expected.containsReversed, "contains reversed")
                let nearest = tree.findLine(PointDouble(20, 11), 5)
                if let expectedNearest = expected.nearest, let nearestLine = nearest.nearestItem {
                    h.expectEqual([nearestLine.start.y, nearestLine.end.y], expectedNearest, "nearest line")
                } else {
                    h.expectNil(nearest.nearestItem, "nearest line (expected nil)")
                }
                h.expectEqual(sortedLineCoords(tree.findAllLinesInRange(PointDouble(40, -5), PointDouble(60, 15)).values()),
                             lexicographicSort(expected.range), "lines in range")
                var iteration: [[Double]] = []
                var iterator = tree.iterator()
                while iterator.hasNext() { iteration.append(coords(iterator.next())) }
                h.expectEqual(iteration, expected.iteration, "AVL line iteration order")
                tree.removeLine(makeLine(makePoint(50, -10), makePoint(50, 30)))
                h.expectEqual(tree.size(), expected.sizeAfterRemove, "size after remove")
                h.expectEqual(tree.isEmpty(), expected.isEmptyAfterRemove, "empty after remove")
                tree.clear()
                h.expectEqual(tree.isEmpty(), expected.isEmptyAfterClear, "empty after clear")
            },
            TestSuite("CoreTree.rbLine") { h in
                let fixture = try Fixtures.decode(TreesFixture.self, "Fixtures/tree/trees.json")
                let expected = fixture.rbLine
                let tree = RedBlackLineTree()
                let lines = expected.lines.map { makeLine(makePoint($0[0], $0[1]), makePoint($0[2], $0[3])) }
                for line in lines { tree.addLine(line) }
                h.expectEqual(tree.size(), expected.size, "RB line tree size")
                h.expectEqual(tree.hasViolation(), expected.violation, "RB line violation")
                let nearest = tree.findLine(PointDouble(0, 0), 1000)
                if let expectedNearest = expected.nearest, let nearestLine = nearest.nearestItem {
                    h.expectEqual(coords(nearestLine), coords(expectedNearest), "RB nearest line")
                } else {
                    h.expectNil(nearest.nearestItem, "RB nearest line (expected nil)")
                }
                h.expectEqual(tree.findLine(PointDouble(-10000, -10000), 1).nearestItem == nil, expected.missIsNull, "RB nearest miss")
                for index in expected.removeIndices { tree.removeLine(lines[index]) }
                h.expectEqual(tree.size(), expected.sizeAfterRemove, "RB size after removes")
                var iteration: [[Double]] = []
                for line in tree { iteration.append(coords(line)) }
                h.expectEqual(iteration, expected.iteration.map(coords), "RB line iteration order == reference JavaMap order")
            },
            TestSuite("CoreTree.rbLineDuplicateKeys") { h in
                let fixture = try Fixtures.decode(TreesFixture.self, "Fixtures/tree/trees.json")
                let expected = fixture.rbLineDuplicateKeys
                let tree = RedBlackLineTree()
                for index in 0..<20 {
                    let base = Double(index * 10)
                    tree.addLine(makeLine(makePoint(0, base), makePoint(0, base + 5)))
                }
                h.expectEqual(tree.size(), expected.sizeBefore, "duplicate-key size")
                h.expectEqual(tree.hasViolation(), expected.violationBefore, "duplicate-key violation")
                let exact = tree.findExact(makeLine(makePoint(0, 10), makePoint(0, 15)))
                if let expectedExact = expected.findExact, let exact {
                    h.expectEqual(coords(exact), coords(expectedExact), "duplicate-key findExact")
                } else {
                    h.expectNil(exact, "duplicate-key findExact (expected nil)")
                }
                h.expectEqual(sortedLineCoords(tree.findAllLinesInRange(PointDouble(-1, 95), PointDouble(1, 125)).values()),
                             lexicographicSort(expected.range), "duplicate-key range")
                for index in 0..<10 {
                    let base = Double(index * 20)
                    tree.removeLine(makeLine(makePoint(0, base), makePoint(0, base + 5)))
                }
                h.expectEqual(tree.size(), expected.sizeAfterRemove, "duplicate-key size after removes")
                h.expectEqual(tree.hasViolation(), expected.violationAfterRemove, "duplicate-key violation after removes")
            },
        ]
    }
}
